def S(w,h,aria,body):return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img" aria-label="{aria}"><title>{aria}</title>{body}</svg>'
tx=lambda x,y,t,sz=14,fill='#0f172a',extra='':f'<text x="{x}" y="{y}" font-size="{sz}" fill="{fill}" font-family="sans-serif" {extra}>{t}</text>'
def tri(vs,labels,stroke='#2563eb',right=None):
    s=f'<polygon points="{" ".join(f"{x},{y}" for x,y in vs)}" fill="#e0f2fe" fill-opacity=".5" stroke="{stroke}" stroke-width="2.4"/>'
    for t,(x,y) in labels:s+=tx(x,y,t)
    return s
